// Where the synced design-playground bundle lives, and what is in it.
// The catalog (embedCatalog.json) is GENERATED by `npm run sync:sd-playground`;
// never hard-code embed hashes or case ids, look them up here by catalog id.

import catalog from "./embedCatalog.json";

const raw = (import.meta.env.VITE_SD_PLAYGROUND_URL || `${import.meta.env.BASE_URL}sd-playground/`).trim();
export const PLAYGROUND_BASE = raw.endsWith("/") ? raw : `${raw}/`;

const byId = new Map(catalog.embeds.map((e) => [e.id, e]));
export const getEmbed = (id) => byId.get(id) || null;
export const catalogStats = { flows: catalog.flows, cases: catalog.cases, generated: catalog.generated };

// "#embed/flow/returns/cs-chat-exchange" + { case, state, theme, motion, bg } -> full iframe URL.
// The playground reads its query from INSIDE the hash.
export function embedUrl(entry, opts = {}) {
  const q = new URLSearchParams();
  for (const k of ["case", "state", "theme", "motion", "bg"]) if (opts[k]) q.set(k, opts[k]);
  const qs = q.toString();
  return `${PLAYGROUND_BASE}index.html${entry.hash}${qs ? `?${qs}` : ""}`;
}

// Offline fallback: a small tracked poster per embed (public/sd-story-posters/<embedId>.png, written by
// `npm run sync:sd-playground` from the playground's own thumbnails). Not every embed has one.
export const embedPoster = (entry) => (entry.kind === "flow" ? `${import.meta.env.BASE_URL}sd-story-posters/${entry.id}.png` : null);

// Is the bundle actually deployed? A single-page-app host answers a missing file with
// index.html and a 200, so check that SYNCED.json parses and carries a commit.
let syncedPromise = null;
export function loadSynced() {
  if (!syncedPromise) {
    syncedPromise = fetch(`${PLAYGROUND_BASE}SYNCED.json`, { cache: "no-cache" })
      .then((r) => (r.ok ? r.json() : null))
      .then((j) => (j && typeof j.commit === "string" ? j : null))
      .catch(() => null);
  }
  return syncedPromise;
}
